//! 🧫️ Authentic Store read issuance, source sealing, independent denials and closure share one original decoder.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
use semio_framework_value::{RetainedCloneGrant,retained_clone::retained_clone_grant_admits};
use semio_framework_value_snapshot_read::snapshot_read_registry_handle::birth::SnapshotReadRegistryBirth;
use semio_framework_value_snapshot_read::{SnapshotReadRegistryAliasRetirement,snapshot_registry_alias_demands,snapshot_registry_alias_close_step};
use std::sync::Arc;
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:100_000,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:256}}
fn clock()->Option<u64>{Some(1)}
fn registry_step(owner:&mut SnapshotReadRegistryBirth,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{
 let demand=owner.demands()?;
 let result=cx.with_native_receiving::<_,semio_framework_value::native_decoding::NativeConstructionStepFailure<ValueError>>(|control|control.receive_construction_step(demand,|control,grant|owner.advance(grant,control)));
 let progress=match &result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};let receipt=cx.consume_receiving_retained(cx.receiving_issued_grant().expect("original registry receiving grant"),progress);cx.consume_fuel(progress.copied_items as u64);
 match(result,receipt){(Ok(_),Ok(()))=>Ok(()),(Err(error),Ok(()))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=Some(receipt);Err(failure)}}
}
fn checked<R>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->R{
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,run));let result=result.expect("same original source and whole native refusal");let receipt=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));result
}
#[test]
fn actual_read_preparation_keeps_its_lease_key_and_caller_through_denied_birth_and_close(){
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(79),Generation(7),stock(),clock,u64::MAX,1_000_000);let mut decoder=OriginalJobDecodeOwner::empty();let mut birth=SnapshotReadRegistryBirth::new();
 for _ in 0..100{if birth.ready().unwrap(){break}checked(&mut caller,&mut decoder,stock(),|cx|registry_step(&mut birth,cx));}assert!(birth.ready().unwrap());
 let registry=checked(&mut caller,&mut decoder,stock(),|cx|{let Some((registry,progress))=birth.take(cx.retained_grant())?else{panic!("funded original registry handoff")};cx.consume_retained(progress)?;cx.consume_fuel(1);Ok(registry)});assert!(birth.terminal_is_empty());drop(birth);
 let mut root=None;let capacity=semio_framework_value::retirement::shared::arc_bytes::<u64>();checked(&mut caller,&mut decoder,stock(),|cx|admit_original_construction(cx,&mut root,OriginalConstructionDemand{items:1,copy_bytes:0,capacity_bytes:capacity,release_bytes:0,depth:1},|_|Ok((Arc::new(37u64),RetainedCloneProgress{copied_items:1,retained_capacity_bytes:capacity,..Default::default()}))));
 let pointer=Arc::as_ptr(root.as_ref().unwrap());let mut read=None;
 checked(&mut caller,&mut decoder,stock(),|cx|admit_original_construction(cx,&mut read,OriginalConstructionDemand{items:1,copy_bytes:size_of::<Arc<u64>>(),capacity_bytes:0,release_bytes:0,depth:1},|_|{let lease=registry.try_issue(Arc::clone(root.as_ref().unwrap())).unwrap_or_else(|_|panic!("original funded vacant registry"));Ok((SnapshotRead::new(root.take().unwrap(),lease),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Arc<u64>>(),..Default::default()}))}));
 let mut source=checked(&mut caller,&mut decoder,stock(),|cx|{let source=OriginalInferenceSource::store_read(read.take().unwrap(),"field Ä",OriginalSourceBinding::borrow(cx));cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<OriginalInferenceSource<u64>>(),..Default::default()})?;cx.consume_fuel(1);Ok(source)});
 let mut foreign=OriginalJobFixtureCaller::admit(OperationId(79),Generation(7),stock(),clock,u64::MAX,100000);let before=match source.original.as_ref().unwrap(){Input::StoreRead(read)=>read.lease_identity(),Input::Owned(_)=>panic!("actual Store read changed source kind")};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn(stock(),|cx|source.admit_step(cx)));assert!(result.is_err());assert_eq!(heap,Default::default());assert_eq!(source.read.as_ref().unwrap().store_lease_identity(),before);assert_eq!(foreign.receipt(),Default::default());foreign.retire(stock());
 for _ in 0..10{if source.complete(){break}let demand=source.admission_demands().unwrap();let exact=RetainedCloneGrant{maximum_items:demand.items,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for axis in 0..5{let mut denied=exact;let value=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};if *value==0{continue}*value-=1;let before=caller.cumulative_receipt();assert!(!checked(&mut caller,&mut decoder,denied,|cx|source.admit_step(cx)));assert_eq!(caller.cumulative_receipt(),before);}checked(&mut caller,&mut decoder,exact,|cx|source.admit_step(cx));}
 assert!(source.complete());assert_eq!(source.snapshot().unwrap()as*const u64,pointer);assert_eq!(source.key().unwrap(),"field Ä");
 let mut registry_close=Some(SnapshotReadRegistryAliasRetirement::new(registry));for _ in 0..10{if registry_close.is_none(){break}let demand=snapshot_registry_alias_demands(&registry_close).unwrap();checked(&mut caller,&mut decoder,stock(),|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,demand,|grant|snapshot_registry_alias_close_step(&mut registry_close,grant))?;Ok(())}));}assert!(registry_close.is_none());
 source.begin_close();for _ in 0..100000{if source.terminal_is_empty(){break}let demand=source.retirement_demands(stock().maximum_copy_bytes).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)};for axis in 0..5{let mut denied=exact;let value=match axis{0=>&mut denied.maximum_items,1=>&mut denied.maximum_copy_bytes,2=>&mut denied.maximum_capacity_bytes,3=>&mut denied.maximum_release_bytes,_=>&mut denied.maximum_depth};if *value==0{continue}*value-=1;let selected=source.retirement_demands(denied.maximum_copy_bytes).unwrap();if retained_clone_grant_admits(denied,selected){continue}let before=caller.cumulative_receipt();checked(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|source.close_step(cx)));assert_eq!(caller.cumulative_receipt(),before);}checked(&mut caller,&mut decoder,exact,|cx|cx.with_original_retirement(|cx|source.close_step(cx)));}
 assert!(source.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source));assert_eq!(heap,Default::default());
 for _ in 0..10000{if decoder.terminal_is_empty(){break}caller.turn(stock(),|cx|cx.with_original_retirement(|cx|{let demand=decoder.retirement_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,demand,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}assert!(decoder.terminal_is_empty());caller.retire(stock());
}
